right.code:
// Keyed correctly, versioned, jittered TTL as a safety net
class DashboardStats
{
    public function for(Tenant $tenant): array
    {
        $version = Cache::get("tenant:{$tenant->id}:stats:v", 1);
        $key = "tenant:{$tenant->id}:stats:v{$version}";
        return Cache::remember($key, now()->addMinutes(10)->addSeconds(random_int(0, 60)), fn () => $this->compute($tenant));
    }
    public function invalidate(Tenant $tenant): void
    {
        Cache::increment("tenant:{$tenant->id}:stats:v");     // old key simply ages out
    }
}

// Invalidate on the write (observer/listener) — the mechanism; TTL is only the net
class OrderObserver { public function saved(Order $o): void { app(DashboardStats::class)->invalidate($o->tenant); } }

// Stampede protection: stale-while-revalidate (Laravel 11.23+)
$stats = Cache::flexible($key, [300, 900], fn () => $this->compute($tenant));
// 0–300s: fresh, served directly. 300–900s: stale served immediately, ONE background refresh. >900s: recompute inline.

// Or explicit single-flight with a lock
$stats = Cache::get($key) ?? Cache::lock("lock:$key", 10)->block(5, function () use ($key) {
    return Cache::remember($key, 600, fn () => $this->compute());  // re-check inside the lock
});

// Tags where the store supports them
Cache::tags(['orders', "tenant:{$tenant->id}"])->remember($key, 600, ...);
Cache::tags(["tenant:{$tenant->id}"])->flush();   // on tenant-wide change

// Per-request memoisation (not Redis): the same lookup 50 times in one request
$tenant = once(fn () => Tenant::find($id));   // Laravel 11 once()

// HTTP caching for public responses
return response()->json($data)->header('Cache-Control', 'public, max-age=60, stale-while-revalidate=300')->setEtag(md5(json_encode($data)));

