class MonthlyRevenue {
    public function for(int $tenantId): array {
        $v = Cache::get("t:$tenantId:rev:v", 1);
        return Cache::remember("t:$tenantId:rev:v$v", 600, fn () => DB::table('orders')
            ->selectRaw("DATE_FORMAT(created_at,'%Y-%m') ym, SUM(total) revenue")
            ->where('tenant_id', $tenantId)->where('status', 'paid')->whereYear('created_at', 2026)
            ->groupBy('ym')->orderBy('ym')->get()->all());
    }
    public function bump(int $tenantId): void { Cache::increment("t:$tenantId:rev:v"); }
}
class OrderObserver { public function saved(Order $o): void { app(MonthlyRevenue::class)->bump($o->tenant_id); } }

public function test_cache_invalidates_on_new_paid_order(): void {
    $svc = app(MonthlyRevenue::class);
    $before = $svc->for(1);
    Order::factory()->create(['tenant_id' => 1, 'status' => 'paid', 'total' => 100, 'created_at' => '2026-05-10']);
    $after = $svc->for(1);
    $this->assertNotEquals($before, $after);
}
// Cache::increment on a missing key sets it to 1 — so the first bump makes version 1→... check: get(...,1) default handles it.

// route
Route::get('/stats', function () {
    return Cache::remember('stats', 10, function () { Log::info('computing'); sleep(2); return ['n' => rand()]; });
});
// wait 10s for expiry, then:  ab -n 20 -c 20 http://127.0.0.1:8000/stats
// grep -c computing storage/logs/laravel.log   → ~20 (every request recomputed)

// fixed
Route::get('/stats', function () {
    return Cache::flexible('stats', [10, 60], function () { Log::info('computing'); sleep(2); return ['n' => rand()]; });
});
// after the fresh window: ab again → 1 'computing', 19 stale hits served instantly
// Note: php artisan serve is single-threaded; use php -S with multiple workers, Octane, or nginx+fpm to see real concurrency.

Mistakes:
1. Global key for user-specific data → every user gets the first user's permissions (security bug).
2. 24h TTL with no invalidation → a revoked permission persists a day.
3. Caches model objects (Permission collection) → large payloads, serialisation coupling.
4. Runs in middleware on every request → fine, but must be cheap: store permission names, not models.

Rewrite:
$names = Cache::remember("user:{$user->id}:perms:v{$user->permissions_version}", 3600, fn () => $user->getAllPermissions()->pluck('name')->all());
// On role/permission change: $user->increment('permissions_version') (or Cache::forget the key). TTL is the safety net.
// spatie/laravel-permission already caches the roles↔permissions map globally and invalidates on change — use that layer and cache only the per-user assignment if needed.
